def cc(n):
    s = ''
    while n != 0:
        s = str(n % 6) +  s
        n //= 6
    return s

def f(n):
    s = cc(n)
    sum_digits = sum(map(int,list(s)))
    if sum_digits % 5 == 0:
        s = s.replace('0','*').replace('3','0').replace('*','3')
        s = '11' + s
    else:
        s += '44'
        s = s[0] + '05' + s[3:]
    return int(s,6)

a = []
for i in range(1,100000):
    if f(i) > 1500:
        a.append([f(i),-i])
a.sort()
print(abs(a[0][1]))
